# Generated by EduBoard IDE. Runs on the MicroPython device.
from machine import Pin, ADC
import time
import dht

eduDht_4 = dht.DHT11(Pin(4))
eduDhtTime_4 = None

def eduReadDht_4(humidity):
    global eduDhtTime_4
    now = time.ticks_ms()
    if eduDhtTime_4 is None or time.ticks_diff(now, eduDhtTime_4) >= 2000:
        try:
            eduDht_4.measure()
            eduDhtTime_4 = now
        except OSError:
            return float("nan")
    return eduDht_4.humidity() if humidity else eduDht_4.temperature()



while True:
  print('Temperature C:')
  print(eduReadDht_4(False))
  print('Humidity %:')
  print(eduReadDht_4(True))
  time.sleep_ms(2000)
